command:example.dev:code:
$ranges = @(
    @{ Start = 1; End = 2 }
    @{ Start = 5; End = 7; OutputName = "part2" }
)
Split-Chapters -InputFile "C:\movie.mkv" -ChapterRanges $ranges -OutputPath "C:\Out"

$ranges = @(
    @{ Start = 1; End = 1 },
    @{ Start = 2; End = 2 },
    @{ Start = 3; End = 3 }
)
Split-SeriesChapters -Title "My Show" -Season 1 -InputFile "C:\season1.mkv" -ChapterRanges $ranges -TvDbSeriesUrl "https://thetvdb.com/series/12345"
